import{_ as t,c as s,o as n,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易原","description":"易原 - 易原","frontmatter":{"title":"易原","description":"易原 - 易原"},"headers":[],"relativePath":"classics/yiyuan/001.md","filePath":"classics/yiyuan/001.md"}'),l={name:"classics/yiyuan/001.md"};function i(c,a,o,d,p,u){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易原",tabindex:"-1"},[r("易原 "),e("a",{class:"header-anchor",href:"#易原","aria-label":"Permalink to “易原”"},"​")],-1),e("p",null,"欽定四庫全書經部一",-1),e("p",null,"易類提要",-1),e("p",null,"臣 等謹案：易原八卷，宋程大昌撰。大昌字泰之，休寧人。紹興二十一年進士，歷官權吏部尚書、龍圖閣直學士。諡文簡。大昌學術湛深，於諸經皆有論說。以易義自漢以來糾紛尤甚，因作是書以貫通之。苦思力索，四年而成。宋藝文志、文獻通考皆著於錄。陳振孫稱其首論五十有五之數，參之圖書，大衍為易之原，而卦變、揲法皆有圖論，往往斷以己見，出先儒之外。今考其所論分爻值日，乃京、焦卦氣，其始於中孚，本用太初法，與夫子所謂「乾坤之策當期之日」者不合。復姤生卦，說始邵子，但乾坤生六子，說卦傳有明文，不得先有六畫之卦，後有三畫之卦。鄭康成用十日、十二辰、二十八宿以應大衍五十之數，本於乾鑿度，與馬融之增北辰，荀爽之增用九、用六，不過以意決比附，初無不易之理。張行成別立二十五數以推大衍，則是五十有五數之外，別有二十五數，更非孔子所曾言。其參互折衷，皆能根據大傳，旁通交推，於易義實有所闡發，不徒文詞之辨博己也。其書久無傳本，惟程敏政新安文獻志載有三篇，故朱彝尊經義考以為已佚。今散見於永樂大典中者，採掇得百有餘篇，尚為完整，謹釐訂編次，分為八卷。大昌禹貢圖說嘗刻入通志堂經解中，脫佚不完，已從永樂大典考輯補正。今是書復為裒綴成編，數百年諸儒未見之本，重得表章傳世，庶俾大昌撰述之苦心藉以不泯焉。乾隆四十九年十月恭校上。",-1),e("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。",-1)])])}const f=t(l,[["render",i]]);export{_ as __pageData,f as default};
